from sympy import Basic
from sympy.codegen.ast import Token, CodegenAST

class _StringContent(Basic):
    '''A Basic that wraps a string value.'''
    __slots__ = ('_text',)

    def __new__(cls, text):
        obj = Basic.__new__(cls)
        obj._text = text
        return obj

    def __str__(self):
        return self._text

    def __repr__(self):
        return f'_StringContent({self._text!r})'

    def __eq__(self, other):
        if isinstance(other, _StringContent):
            return self._text == other._text
        return False

    def _hashable_content(self):
        return (self._text,)


# Create a String class that uses _StringContent internally
class TestString(CodegenAST):
    __slots__ = ('text',)
    not_in_args = ['text']  # Keep _args empty
    is_Atom = True

    def __new__(cls, text):
        # text is the actual string
        obj = CodegenAST.__new__(cls)  # No args
        obj.text = text  # Store as plain string
        return obj

    @property
    def args(self):
        # Return _StringContent for invariance, but keep _args empty
        return (_StringContent(self.text),)

    def __str__(self):
        return self.text

    def __repr__(self):
        return f'TestString({self.text!r})'

    def __eq__(self, other):
        if not isinstance(other, TestString):
            return False
        return self.text == other.text

    def _hashable_content(self):
        return (self.text,)

    def _sympystr(self, printer, *args, **kwargs):
        return self.text


# Test
s = TestString('foo')
print('TestString(\"foo\"):')
print('  s:', s)
print('  s.text:', s.text)
print('  s.args:', s.args)
print('  s._args:', s._args)

# Test invariance
print()
print('Invariance:')
print('  s.func(*s.args):', s.func(*s.args))
print('  s.func(*s.args) == s:', s.func(*s.args) == s)
